        practice_exercise="Apply StandardScaler to California Housing. Fit on training data, transform both train and test. Verify train mean≈0 and std≈1.",
        quiz=[
            QuizQuestion("Why must you fit the scaler on training data only?", ["It's faster", "To prevent data leakage — test data statistics shouldn't influence scaling", "pandas requires it", "Scalers can't handle test data"], 1, "Fitting on test data leaks test statistics into training, giving unrealistically good performance."),
            QuizQuestion("Which models do NOT require feature scaling?", ["KNN and SVM", "Linear Regression and Logistic Regression", "Random Forest and Gradient Boosting", "All models require scaling"], 2, "Tree-based models (Random Forest, XGBoost) split on feature thresholds, so scale doesn't affect them."),
        ],
        takeaways=["StandardScaler is the default choice", "Tree-based models don't need scaling", "Always fit on train, transform on test"],
        lab_module="feature_engineering",
