        practice_exercise="Apply VarianceThreshold(threshold=0.01) to California Housing after scaling. Which features are removed?",
        quiz=[
            QuizQuestion("VarianceThreshold should be applied:", ["Before scaling", "After scaling", "Before splitting data", "Only on categorical features"], 1, "Scaling affects variance, so apply VarianceThreshold after scaling to get meaningful variance values."),
            QuizQuestion("A feature where 99% of values are the same has:", ["High variance", "Near-zero variance", "Medium variance", "Infinite variance"], 1, "When nearly all values are identical, the feature has very little variance and provides minimal information."),
        ],
        takeaways=["Near-zero variance features are likely useless", "Apply AFTER scaling if features have different units", "Always verify what was removed"],
        lab_module="feature_engineering",
