    Topic(
        id="fe_19", title="Multicollinearity", section="feature_engineering", order=19, difficulty="advanced",
        objectives=["Detect multicollinearity using VIF", "Understand its effect on linear models", "Apply remedies"],
        concept="Multicollinearity occurs when two or more features are highly linearly related. It inflates coefficient standard errors in linear models, making them unreliable. Variance Inflation Factor (VIF) > 5-10 indicates problematic multicollinearity.",
        why_matters="Multicollinearity doesn't hurt tree-based models but severely damages linear regression, logistic regression, and SVM. It makes feature importance unreliable.",
        example="California Housing: 'total_rooms' and 'total_bedrooms' are highly correlated (r=0.93). In linear regression, their individual coefficients become unstable — one might be positive, the other negative, despite both being positively correlated with price.",
        python_example="```python\nfrom statsmodels.stats.outliers_influence import variance_inflation_factor\nimport pandas as pd\n\n# Compute VIF for each feature\nX_num = df.select_dtypes('number').dropna()\nvif_data = pd.DataFrame()\nvif_data['feature'] = X_num.columns\nvif_data['VIF'] = [variance_inflation_factor(X_num.values, i)\n                   for i in range(X_num.shape[1])]\nprint(vif_data.sort_values('VIF', ascending=False))\n\n# VIF > 10 → severe multicollinearity\n# VIF > 5 → moderate\n# VIF < 5 → acceptable\n```",
        common_mistakes=[
            "Ignoring multicollinearity in linear models (coefficients become meaningless)",
            "Using VIF with categorical features (encode first)",
            "Removing all correlated features when only one pair is problematic",
        ],
        practice_exercise="Compute VIF for California Housing. Which features have VIF > 10? What would you do about them?",
        quiz=[
            QuizQuestion("VIF > 10 indicates:", ["No multicollinearity", "Moderate multicollinearity", "Severe multicollinearity", "Perfect multicollinearity"], 2, "VIF > 10 means the feature's variance is inflated 10× due to correlation with other features — severe multicollinearity."),
            QuizQuestion("Multicollinearity primarily affects:", ["Tree-based models", "Linear models (regression, logistic)", "KNN", "Clustering algorithms"], 1, "Linear models estimate individual coefficients — multicollinearity makes these estimates unstable. Trees don't estimate coefficients."),
        ],
        takeaways=["VIF > 10 indicates severe multicollinearity", "Multicollinearity hurts linear models but not tree-based models", "Remedies: remove a feature, use PCA, or use regularised regression (Ridge)"],
        lab_module="feature_engineering",
    ),
